-- One row per sales region. regionCode is the Ermine `region` value every view exposes.
CREATE TABLE dim_region (
  regionId INTEGER NOT NULL,
  regionCode TEXT NOT NULL,
  regionName TEXT NOT NULL,
  regionGroup TEXT NOT NULL,
  countryName TEXT NOT NULL,
  countryCode TEXT NOT NULL,
  populationWeight REAL NOT NULL,
  CONSTRAINT pk_dim_region PRIMARY KEY (regionId),
  CONSTRAINT uq_dim_region_regionCode UNIQUE (regionCode)
) STRICT;

-- The catalogue. productName is the Ermine `item` value (Sales.e).
CREATE TABLE dim_product (
  productId INTEGER NOT NULL,
  sku TEXT NOT NULL,
  productName TEXT NOT NULL,
  category TEXT NOT NULL,
  subCategory TEXT NOT NULL,
  priceBand TEXT NOT NULL,
  listPrice REAL NOT NULL,
  unitCost REAL NOT NULL,
  CONSTRAINT pk_dim_product PRIMARY KEY (productId),
  CONSTRAINT uq_dim_product_sku UNIQUE (sku),
  CONSTRAINT uq_dim_product_productName UNIQUE (productName)
) STRICT;

