  quantity INTEGER NOT NULL,
  unitPrice REAL NOT NULL,
  discountPct REAL NOT NULL,
  lineAmount REAL NOT NULL,
  promoCode TEXT NULL,
  CONSTRAINT pk_fact_order_line PRIMARY KEY (orderId, lineNo),
  CONSTRAINT fk_fact_order_line_orderDate FOREIGN KEY (orderDate) REFERENCES dim_date (day),
  CONSTRAINT fk_fact_order_line_regionId FOREIGN KEY (regionId) REFERENCES dim_region (regionId),
  CONSTRAINT fk_fact_order_line_customerId FOREIGN KEY (customerId) REFERENCES dim_customer (customerId),
  CONSTRAINT fk_fact_order_line_productId FOREIGN KEY (productId) REFERENCES dim_product (productId),
