  CONSTRAINT fk_fact_order_line_channelId FOREIGN KEY (channelId) REFERENCES dim_channel (channelId)
) STRICT;

-- A sales target per region per quarter; the `targets` view sums them per region.
CREATE TABLE fact_target (
  regionId INTEGER NOT NULL,
  yearNo INTEGER NOT NULL,
  quarterNo INTEGER NOT NULL,
  targetAmount REAL NOT NULL,
  CONSTRAINT pk_fact_target PRIMARY KEY (regionId, yearNo, quarterNo),
  CONSTRAINT fk_fact_target_regionId FOREIGN KEY (regionId) REFERENCES dim_region (regionId)
) STRICT;

-- Backs Doc/SalesReport.e (sales : [srRegion, srSales, srDelta]). A BASE TABLE (a mart snapshot) at every tier: its xs values are literals no view over the 8 sales can derive.
